 const businesses=['Hana Kitchen','Farid Print Studio','Meena Tailoring','Azlan Mobile Care','Nadia Bakes','Ravi Grocer','Sofia Florals','Hafiz Coffee','Priya Beauty','Amir Catering','Alya Craft','Hakim Meals','Leela Home Foods','Faiz Cycle Care','Sara Cookies','Danish Design','Maya Boutique','Irfan Drinks','Rina Studio','Zaid Repairs','Anita Snacks','Fikri Laundry','Lina Cakes','Shafiq Tech','Nora Meals','Imran Car Wash','Tina Flowers','Asyraf Burger','Dina Crafts','Johan Fresh Mart'];
 const people=names.map((name,i)=>({id:'EKU-'+String(i+1).padStart(3,'0'),name,business:businesses[i],programme:i%3===0?'Digital Marketing':'Accelerator',cohort:cohorts[Math.floor(i/10)].id,state:cohorts[Math.floor(i/10)].state,gender:i<20?'Female':'Male',age:25+i%27,background:i<21?'B40':i<26?'Asnaf':'PWD',sector:['F&B','Retail','Fashion','Services'][i%4],mentor:i<20?'U1':'U2',email:'participant'+(i+1)+'@example.test',phone:'',goal:'Build a more consistent customer base.',photo:'',access:true,classTarget:i%3===0?2:4,moduleIds:i%3===0?['M1','M2']:['M1','M2','M3'],baseline:{sales:3500+i*55,cost:2100},checkins:['2026-07','2026-08','2026-09'].filter((_,m)=>!(m===2&&i%6===5)).map((month,m)=>({month,sales:3700+i*55+(m*230),cost:2200+m*60,notes:'Practising a weekly content plan and keeping sales records.',milestone:i%4!==0,reviewed:i%3!==0,story:i%7===0?'I now plan my weekly posts and record my orders. It is easier to see which products customers return for.':'',consent:i%7===0})),learning:{}}));
 people.forEach((p,i)=>p.moduleIds.forEach((id,j)=>{const m=modules.find(x=>x.id===id);const complete=i%5!==4&&(j===0||i%3===1);const reviewed=complete?m.resources.map(r=>r.id):i%4===0?[m.resources[0].id]:[];p.learning[id]={revision:1,reviewed,notes:{},attempts:complete?[{score:100,passed:true,date:'2026-09-28T09:00:00Z',answers:m.quiz.map(q=>q.correct)}]:[]};}));
 const users=[{id:'U0',name:'Programme admin',role:'admin',cohorts:['01','02','03'],active:true},{id:'U1',name:'Aina Rahman',role:'mentor',cohorts:['01','02'],active:true},{id:'U2',name:'Daniel Lee',role:'mentor',cohorts:['03'],active:true},{id:'U3',name:'Maxis representative',role:'stakeholder',cohorts:['01','02','03'],active:true},{id:'U4',name:'Regional stakeholder',role:'stakeholder',cohorts:['03'],active:true}];
 const sessions=[];cohorts.forEach(c=>programmes.forEach(programme=>{const roster=people.filter(p=>p.programme===programme&&p.cohort===c.id).map(p=>p.id);[1,2].forEach(number=>sessions.push({id:'S'+sessions.length,programme,cohort:c.id,number,date:number===1?'2026-09-10':'2026-09-24',title:number===1?'Customer discovery workshop':'Digital marketing clinic',finalized:true,hasSnapshot:true,roster,marks:Object.fromEntries(roster.map((id,i)=>[id,i===2&&number===2?'absent':'present']))}));}));
 return {version:3,programmes,cohorts,people,modules,users,sessions,audit:[]};
